INSERT INTO exercises (id, lesson_id, title, instruction, audio_url, content, exercise_type, skill_type, time_limit, max_attempts, passing_score, ordering)
VALUES
    ('ad96d65b-5c3a-5057-9e9c-39bb9f76d4ee', NULL, 'Listening Section 1 - Photography Course Enquiry', 'You will hear a telephone conversation between a woman and a receptionist at an arts centre. Answer Questions 1-10.', 'https://example.com/audio/listening-01.mp3', '{"sectionTitle":"Section 1","transcript":[{"speaker":"Tom","text":"Good morning, Riverside Community Arts Centre. Tom speaking."},{"speaker":"Maria","text":"Hello. I saw your poster for the weekend photography course and I''d like to find out a bit more."},{"speaker":"Tom","text":"Of course. Can I take some details first? What''s your name?"},{"speaker":"Maria","text":"It''s Maria Thornley."},{"speaker":"Tom","text":"Could you spell your surname for me?"},{"speaker":"Maria","text":"Yes, it''s T-H-O-R-N-L-E-Y."},{"speaker":"Tom","text":"Thank you. And a contact number?"},{"speaker":"Maria","text":"My mobile is 07700 493826."},{"speaker":"Tom","text":"07700 493826. Got it. Now, the course starts on the twelfth of March, I think... sorry, let me check. No, I''ve got an updated timetable here. It''s been moved back a week, so it starts on the nineteenth of March."},{"speaker":"Maria","text":"That''s fine, actually it''s better for me."},{"speaker":"Tom","text":"Great. The fee is ninety-five pounds, but members of the centre get a discount. Are you a member?"},{"speaker":"Maria","text":"Yes, I joined last year."},{"speaker":"Tom","text":"Then it''s eighty-five pounds for you."},{"speaker":"Maria","text":"Good. Is it held in the main hall?"},{"speaker":"Tom","text":"No, the main hall is being repainted, so the classes are in Room 14, on the first floor."},{"speaker":"Maria","text":"Room 14. Okay. Do I need to bring my own equipment?"},{"speaker":"Tom","text":"You need your own camera, of course, and a tripod. We have a few spare ones, but there aren''t many, so it''s best to bring your own."},{"speaker":"Maria","text":"I''ll do that."},{"speaker":"Tom","text":"Can I ask what made you interested in the course? Is it for your work?"},{"speaker":"Maria","text":"No, nothing like that, and I''m not planning any trips either. I was given a new camera as a birthday present last month and I''d really like to learn how to use it properly."},{"speaker":"Tom","text":"That''s a good reason to join."},{"speaker":"Maria","text":"What will we be doing in the first session?"},{"speaker":"Tom","text":"The tutor, Dev, takes everyone into the old town to photograph buildings. People often expect landscapes, but we save those for the second weekend, and we don''t do portraits on this course."},{"speaker":"Maria","text":"How big are the classes?"},{"speaker":"Tom","text":"Last year we had fifteen students, which was too many, so this year the limit is twelve."},{"speaker":"Maria","text":"Lovely. And what happens on the last day?"},{"speaker":"Tom","text":"On the final day we put up an exhibition of everyone''s best photographs in the cafe downstairs, and friends and family can come along. Some people expect a trip to a gallery, but that isn''t possible this year, and feedback is given in person rather than online."},{"speaker":"Maria","text":"That sounds wonderful. Thank you for your help."},{"speaker":"Tom","text":"You''re welcome. See you on the nineteenth, then."}]}'::jsonb, 'PRACTICE', 'LISTENING', 600, 99, 0, 1),
    ('d9f52c7a-9133-51eb-ad99-e9fef11162b4', NULL, 'Reading Passage 1 - Farming in the Sky', 'You should spend about 20 minutes on Questions 1-13, which are based on Reading Passage 1 below.', NULL, '{"passageTitle":"Farming in the Sky","paragraphs":[{"label":"A","text":"Cities have long been seen as places that consume food rather than produce it. Farmland lies far beyond the suburbs, and a typical vegetable may travel hundreds of kilometres before it reaches a supermarket shelf. Over the past two decades, however, a growing number of city dwellers have begun to challenge this assumption by planting crops on the one resource that urban areas have in abundance: unused roof space."},{"label":"B","text":"Growing plants on top of buildings is not a modern invention. Raised gardens were a feature of many ancient cities, where they provided shade and a convenient place to grow herbs. What has changed is the scale and the purpose. In 2012, a small company in a northern port city converted the roof of a disused warehouse into a vegetable farm covering four thousand square metres. It was among the first rooftop farms intended to make a profit rather than serve as a hobby or a community project, and its success encouraged similar businesses to open in other cities."},{"label":"C","text":"Supporters point out that a planted roof offers benefits beyond food. A layer of soil and leaves absorbs heat that would otherwise pass into the building, and in summer the rooms below can be several degrees cooler, which reduces the need for air conditioning. The same layer holds rainwater like a sponge, easing the pressure on drains during heavy storms. In addition, the plants capture dust and pollution from the air, and the green space provides a habitat for bees and birds that have few other places to live in dense urban districts."},{"label":"D","text":"The practical difficulties are considerable, however. Soil is heavy, and a saturated layer only fifteen centimetres deep can weigh more than most older roofs were designed to carry. Before any planting begins, an engineer must inspect the structure, and many buildings fail this test. To reduce the load, growers often replace ordinary soil with a lightweight mixture of crushed volcanic rock and recycled compost. Wind is another problem, since crops several storeys above the street dry out quickly and can be damaged by strong gusts. Installing a reliable water supply adds further cost."},{"label":"E","text":"The economics are equally challenging. Rooftop farms cannot compete with large rural farms on price, so most sell premium products such as salad leaves and herbs directly to restaurants, which will pay more for produce picked on the same day. Some farms earn additional income by running workshops for schools and offering the space for private events. Critics argue that rooftop farming will never feed a city. One study suggested that, even if every suitable roof in a large city were planted, the harvest would supply only a small fraction of the vegetables its residents eat."},{"label":"F","text":"Defenders of the movement reply that food production is only part of the story. Many rooftop farms employ local residents who have struggled to find work, and children who visit them often learn for the first time where vegetables come from. In this view, the greatest value of the rooftop farm may be its power to change how city dwellers think about food, rather than the number of tonnes it produces."}]}'::jsonb, 'PRACTICE', 'READING', 1200, 99, 0, 1);
INSERT INTO question_groups (id, exercise_id, group_title, group_instruction, passage_reference, image_url, question_type, question_range, correct_answer_count, ordering)
