    ('5d8cca4d-772e-5a7c-964e-41edcfa81c01', 'ad96d65b-5c3a-5057-9e9c-39bb9f76d4ee', 'Questions 1-6', 'Complete the form below. Write ONE WORD AND/OR A NUMBER for each answer.', NULL, NULL, 'FILL_BLANK', '1-6', 6, 1),
    ('0ba98a28-4a43-5ec2-9eeb-a3c882a0fe0d', 'ad96d65b-5c3a-5057-9e9c-39bb9f76d4ee', 'Questions 7-10', 'Choose the correct letter, A, B or C.', NULL, NULL, 'MULTIPLE_CHOICE', '7-10', 4, 2),
    ('b177f263-6e77-51f2-8921-356e3fc88497', 'd9f52c7a-9133-51eb-ad99-e9fef11162b4', 'Questions 1-5', 'Do the following statements agree with the information given in Reading Passage 1? Choose TRUE if the statement agrees with the information, FALSE if the statement contradicts the information, or NOT GIVEN if there is no information on this.', NULL, NULL, 'TRUE_FALSE', '1-5', 5, 1),
    ('8d948892-b330-556f-a87f-ce021c17ff1f', 'd9f52c7a-9133-51eb-ad99-e9fef11162b4', 'Questions 6-9', 'Complete the sentences below. Choose ONE WORD ONLY from the passage for each answer.', NULL, NULL, 'FILL_BLANK', '6-9', 4, 2),
    ('4d50d879-ab41-54ba-bfba-7a98dc16e42e', 'd9f52c7a-9133-51eb-ad99-e9fef11162b4', 'Questions 10-11', 'Choose the correct letter, A, B, C or D.', NULL, NULL, 'MULTIPLE_CHOICE', '10-11', 2, 3),
    ('00286d12-9c7e-5143-a30c-877285eaf687', 'd9f52c7a-9133-51eb-ad99-e9fef11162b4', 'Questions 12-13', 'Reading Passage 1 has six paragraphs, A-F. Which paragraph contains the following information? Choose the correct letter, A-F.', NULL, NULL, 'MATCHING', '12-13', 2, 4);
