    ('5a8e2a7c-baa7-54f9-acdf-e76f5a7ae6ff', 'ad96d65b-5c3a-5057-9e9c-39bb9f76d4ee', '5d8cca4d-772e-5a7c-964e-41edcfa81c01', 'Surname: ______', 'FILL_BLANK', NULL, NULL, NULL, 'The surname is spelled out: T-H-O-R-N-L-E-Y.', 1, 1),
    ('19ffbce4-38a2-5631-adfa-58fc0880f6c2', 'ad96d65b-5c3a-5057-9e9c-39bb9f76d4ee', '5d8cca4d-772e-5a7c-964e-41edcfa81c01', 'Mobile number: 07700 ______', 'FILL_BLANK', NULL, NULL, NULL, 'Maria gives her mobile number as 07700 493826.', 1, 2),
    ('f52b6ce5-d8cc-5ac6-8116-2b8212582329', 'ad96d65b-5c3a-5057-9e9c-39bb9f76d4ee', '5d8cca4d-772e-5a7c-964e-41edcfa81c01', 'Course starts on: ______ March', 'FILL_BLANK', NULL, NULL, NULL, 'Tom first says the twelfth, then corrects it: the course has moved back a week and starts on the nineteenth.', 1, 3),
    ('cf1415ae-cb29-5e45-8ef8-89bee35bbf70', 'ad96d65b-5c3a-5057-9e9c-39bb9f76d4ee', '5d8cca4d-772e-5a7c-964e-41edcfa81c01', 'Fee for members: £______', 'FILL_BLANK', NULL, NULL, NULL, 'The standard fee is 95 pounds, but Maria is a member so she pays 85 pounds.', 1, 4),
    ('2bd3da34-ceff-5f98-9c0c-bddf87344b11', 'ad96d65b-5c3a-5057-9e9c-39bb9f76d4ee', '5d8cca4d-772e-5a7c-964e-41edcfa81c01', 'Classes are held in Room ______', 'FILL_BLANK', NULL, NULL, NULL, 'The main hall is being repainted, so classes are in Room 14.', 1, 5),
    ('5ac41323-febc-500f-bbe9-38f7a1f7b344', 'ad96d65b-5c3a-5057-9e9c-39bb9f76d4ee', '5d8cca4d-772e-5a7c-964e-41edcfa81c01', 'Students should bring their own camera and ______', 'FILL_BLANK', NULL, NULL, NULL, 'Tom says students need their own camera and a tripod.', 1, 6),
    ('b53b4845-1639-50eb-a873-18b191a9c6a3', 'ad96d65b-5c3a-5057-9e9c-39bb9f76d4ee', '0ba98a28-4a43-5ec2-9eeb-a3c882a0fe0d', 'Why does Maria want to take the course?', 'MULTIPLE_CHOICE', NULL, NULL, NULL, 'She says it is not for work and she has no trip planned. She received a new camera as a gift and wants to learn to use it.', 1, 7),
    ('5a22b3cf-a071-5c45-9031-187b7db92d47', 'ad96d65b-5c3a-5057-9e9c-39bb9f76d4ee', '0ba98a28-4a43-5ec2-9eeb-a3c882a0fe0d', 'What will the class photograph in the first session?', 'MULTIPLE_CHOICE', NULL, NULL, NULL, 'The tutor takes everyone into the old town to photograph buildings. Landscapes are saved for the second weekend and there are no portraits.', 1, 8),
    ('e0765bf4-502f-587e-be8d-83a5db8036f8', 'ad96d65b-5c3a-5057-9e9c-39bb9f76d4ee', '0ba98a28-4a43-5ec2-9eeb-a3c882a0fe0d', 'What is the maximum number of students in each class this year?', 'MULTIPLE_CHOICE', NULL, NULL, NULL, 'Last year there were fifteen students, which was too many. This year the limit is twelve.', 1, 9),
    ('70fdb645-e1bf-5bc0-8c4e-23687e4b63c0', 'ad96d65b-5c3a-5057-9e9c-39bb9f76d4ee', '0ba98a28-4a43-5ec2-9eeb-a3c882a0fe0d', 'What will happen on the final day of the course?', 'MULTIPLE_CHOICE', NULL, NULL, NULL, 'There will be an exhibition of the students'' best photographs. A gallery trip is not possible and feedback is given in person, not online.', 1, 10),
    ('23d97142-77f1-51e7-b12e-02466856c7cf', 'd9f52c7a-9133-51eb-ad99-e9fef11162b4', 'b177f263-6e77-51f2-8921-356e3fc88497', 'Gardens on top of buildings already existed in ancient cities.', 'TRUE_FALSE', NULL, NULL, NULL, 'Paragraph B: growing plants on top of buildings is not a modern invention, and raised gardens were a feature of many ancient cities.', 1, 1),
    ('06409cf7-78ad-555c-9ff1-47c515aef793', 'd9f52c7a-9133-51eb-ad99-e9fef11162b4', 'b177f263-6e77-51f2-8921-356e3fc88497', 'The warehouse farm was designed as a community project rather than a business.', 'TRUE_FALSE', NULL, NULL, NULL, 'Paragraph B: it was among the first rooftop farms intended to make a profit rather than serve as a hobby or a community project.', 1, 2),
    ('f1aadd16-549c-5066-aae3-1ff465aa49c2', 'd9f52c7a-9133-51eb-ad99-e9fef11162b4', 'b177f263-6e77-51f2-8921-356e3fc88497', 'A planted roof can make the rooms below it cooler in summer.', 'TRUE_FALSE', NULL, NULL, NULL, 'Paragraph C: in summer the rooms below can be several degrees cooler.', 1, 3),
    ('669c44f7-8c82-5aad-865e-6e5ee1c52dbc', 'd9f52c7a-9133-51eb-ad99-e9fef11162b4', 'b177f263-6e77-51f2-8921-356e3fc88497', 'Rooftop farms use more water than farms in the countryside.', 'TRUE_FALSE', NULL, NULL, NULL, 'The passage only says that installing a water supply adds cost (paragraph D). It does not compare water use with rural farms.', 1, 4),
    ('81efeadb-f19d-5743-8093-6b103f4071af', 'd9f52c7a-9133-51eb-ad99-e9fef11162b4', 'b177f263-6e77-51f2-8921-356e3fc88497', 'Engineers have found that most older roofs can carry a layer of wet soil without any changes.', 'TRUE_FALSE', NULL, NULL, NULL, 'Paragraph D: a saturated layer of soil can weigh more than most older roofs were designed to carry.', 1, 5),
    ('2c728482-6cde-5ed5-8509-b6caff42fe40', 'd9f52c7a-9133-51eb-ad99-e9fef11162b4', '8d948892-b330-556f-a87f-ce021c17ff1f', 'A layer of soil and leaves holds rainwater like a ______, which eases the pressure on drains during heavy storms.', 'FILL_BLANK', NULL, NULL, NULL, 'Paragraph C: the same layer holds rainwater like a sponge.', 1, 6),
    ('d1d23d4d-3d03-57f2-9ee8-de61f385a125', 'd9f52c7a-9133-51eb-ad99-e9fef11162b4', '8d948892-b330-556f-a87f-ce021c17ff1f', 'To reduce the load on the roof, growers mix crushed volcanic rock with recycled ______.', 'FILL_BLANK', NULL, NULL, NULL, 'Paragraph D: a lightweight mixture of crushed volcanic rock and recycled compost.', 1, 7),
    ('7526993d-9236-5ab0-9673-30fec3c1ceb1', 'd9f52c7a-9133-51eb-ad99-e9fef11162b4', '8d948892-b330-556f-a87f-ce021c17ff1f', 'Most rooftop farms sell their premium products directly to ______.', 'FILL_BLANK', NULL, NULL, NULL, 'Paragraph E: most sell premium products such as salad leaves and herbs directly to restaurants.', 1, 8),
    ('2fb9dcd4-69f6-57c3-b645-1751a4617ec5', 'd9f52c7a-9133-51eb-ad99-e9fef11162b4', '8d948892-b330-556f-a87f-ce021c17ff1f', 'Some farms earn additional income by running ______ for schools.', 'FILL_BLANK', NULL, NULL, NULL, 'Paragraph E: some farms earn additional income by running workshops for schools.', 1, 9),
    ('0cbdd4e0-23b4-5e4d-9596-ef70ced9531e', 'd9f52c7a-9133-51eb-ad99-e9fef11162b4', '4d50d879-ab41-54ba-bfba-7a98dc16e42e', 'According to paragraph D, why must an engineer inspect a building before planting begins?', 'MULTIPLE_CHOICE', NULL, NULL, NULL, 'Paragraph D: wet soil can weigh more than most older roofs were designed to carry. Wind is mentioned as a separate problem.', 1, 10),
    ('9090e9f8-3039-5eab-af64-8b20359edf98', 'd9f52c7a-9133-51eb-ad99-e9fef11162b4', '4d50d879-ab41-54ba-bfba-7a98dc16e42e', 'What is the main point made in paragraph F?', 'MULTIPLE_CHOICE', NULL, NULL, NULL, 'Paragraph F: the greatest value may be the power to change how city dwellers think about food, rather than the number of tonnes produced.', 1, 11),
    ('feb78671-119a-5e78-bf9f-b69e772dd07d', 'd9f52c7a-9133-51eb-ad99-e9fef11162b4', '00286d12-9c7e-5143-a30c-877285eaf687', 'a reference to animals that benefit from green space in the city', 'MATCHING', NULL, NULL, NULL, 'Paragraph C mentions a habitat for bees and birds.', 1, 12),
    ('cc6c9ddd-1dfa-5b69-b970-b6e8f2efd803', 'd9f52c7a-9133-51eb-ad99-e9fef11162b4', '00286d12-9c7e-5143-a30c-877285eaf687', 'a claim that rooftop farms could supply only a small part of a city''s vegetables', 'MATCHING', NULL, NULL, NULL, 'Paragraph E: one study suggested the harvest would supply only a small fraction of the vegetables residents eat.', 1, 13);
